impl SNRT {
    pub fn pack<'b, A: ::flatbuffers::Allocator + 'b>(
        &self,
        _fbb: &mut ::flatbuffers::FlatBufferBuilder<'b, A>
    ) -> ::flatbuffers::WIPOffset<SNR<'b>> {
        let SENSOR_ID = Some({
            let x = &self.SENSOR_ID;
            _fbb.create_string(x)
        });
        let NAME = self.NAME.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let NORAD_CAT_ID = self.NORAD_CAT_ID;
        let OBJECT_ID = self.OBJECT_ID.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let SITE_ID = self.SITE_ID.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let ENTITY_ID = self.ENTITY_ID.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let TYPE = self.TYPE;
        let EMISSION = self.EMISSION;
        let SPECTRAL_BANDS = self.SPECTRAL_BANDS.as_ref().map(|x|{
            let w: alloc::vec::Vec<_> = x.iter().map(|t| t.pack(_fbb)).collect();_fbb.create_vector(&w)
        });
        let FIELD_OF_VIEW = self.FIELD_OF_VIEW.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let FIELD_OF_VIEW_PROVENANCE = self.FIELD_OF_VIEW_PROVENANCE.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let MOUNTING = self.MOUNTING.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let RF = self.RF.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let OPTICAL = self.OPTICAL.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let PROVENANCE = self.PROVENANCE.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let NOTES = self.NOTES.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        SNR::create(_fbb, &SNRArgs{
            SENSOR_ID,
            NAME,
            NORAD_CAT_ID,
            OBJECT_ID,
            SITE_ID,
            ENTITY_ID,
            TYPE,
            EMISSION,
            SPECTRAL_BANDS,
            FIELD_OF_VIEW,
            FIELD_OF_VIEW_PROVENANCE,
            MOUNTING,
            RF,
            OPTICAL,
            PROVENANCE,
            NOTES,
        })
    }
}

